# core skeleton (uses ITTA/DomainBed style)
class MetaAdapter(nn.Module):
    """g_phi: predicts (gamma,beta) for each BN layer given batch stats"""
    def __init__(self, bn_shapes):
        super().__init__()
        self.mlp = nn.Sequential(nn.Linear(sum(c for c,_ in bn_shapes)*2+1, 512),
                                 nn.ReLU(), nn.Linear(512, 2*sum(c for c,_ in bn_shapes)))
        self.bn_shapes = bn_shapes
    def forward(self, stats, entropy):
        x = torch.cat(stats+[entropy.view(1)], dim=0)
        out = self.mlp(x)
        splits = torch.split(out, [2*c for c,_ in self.bn_shapes])
        gammas, betas = [], []
        for (c,_), vec in zip(self.bn_shapes, splits):
            gammas.append(vec[:c]); betas.append(vec[c:])
        return gammas, betas

class MAOF(nn.Module):
    def __init__(self, backbone):
        super().__init__(); self.net = backbone.eval();
        # collect BN modules
        self.bns = [m for m in self.net.modules() if isinstance(m, nn.BatchNorm2d)]
        shapes = [(m.weight.shape[0], i) for i,m in enumerate(self.bns)]
        self.adapter = MetaAdapter(shapes)
    @torch.no_grad()
    def forward(self, x):
        # gather current batch stats
        stats = []
        hooks=[]
        def save_stats(mod,input,output):
            mu=output.mean((0,2,3)); var=output.var((0,2,3), unbiased=False)
            stats.append(mu); stats.append(var)
        for bn in self.bns:
            hooks.append(bn.register_forward_hook(save_stats))
        logits = self.net(x)  # one forward to get stats
        for h in hooks: h.remove()
        entropy = (-logits.softmax(1)*logits.log_softmax(1)).sum(1).mean()
        gammas, betas = self.adapter(stats, entropy.detach())
        # apply modulation and re-run forward
        for bn, g, b in zip(self.bns, gammas, betas):
            bn.weight.data = bn.weight.data + g.to(bn.weight.device)
            bn.bias.data   = bn.bias.data   + b.to(bn.bias.device)
        return self.net(x)

