        vars=[f.var((0,*range(2,f.dim())),unbiased=False) for f in feats]
        skew=[((f-means[i][None,...])**3).mean((0,*range(2,f.dim()))) for i,f in enumerate(feats)]
        ent=(-_.softmax(1)*_.log_softmax(1)).sum(1).mean().repeat(sum(ch))
        return torch.stack(means+vars+skew).view(4,-1), ent[None]
    def forward(self,x,eta):
